into #req_order_ids
from scm.tab.dimServiceorder tdso
inner join dim.turbine dt
on dt.UnitId = tdso.UnitID
and dt.validTo like '%9999%'
where tdso.year between 2000 and 2026
and dt.MainPlatform in ('2MW','3MW','V52/V60','V82/NM72','V90 3MW','Vidar')
