-- 3. Collect the orders containing the required material ids under the relevant events - 1:11min
Drop table if exists #mat_orders;
select roi.ServiceOrderNumber, 
em.Itemnumber, sap.MaterialText
into #mat_orders
from aa.vwsapmaterials sap
inner join #mat_ids em
on em.Itemnumber = sap.Material
inner join #req_order_ids roi
on roi.ServiceOrderNumber = sap.ServiceOrderNumber;

-- 4. Aggregate the data at material level and get the count of orders
select distinct Itemnumber, MaterialText,
count(distinct ServiceOrderNumber) as num_orders
from #mat_orders 
group by Itemnumber, MaterialText;


-- 5. Alternate query to retrieve material vs orders
select Material, MaterialText,
Year(Start_ActualOrBasic) as year_order,
ServiceOrderNumber 
from aa.vwsapmaterials
where ServiceOrderNumber is not null
and Year(Start_ActualOrBasic)>2000;